const mongoose = require('mongoose');

/**
 * Recommendation Schema
 * Stores personalized, explainable financial recommendations generated by
 * the rule-based engine and prioritized by user behavior classification.
 */
const recommendationSchema = new mongoose.Schema(
  {
    userId: {
      type: mongoose.Schema.Types.ObjectId,
      ref: 'User',
      required: true,
      index: true,
    },
    ruleId: {
      type: String,
      required: true,
    },
    title: {
      type: String,
      required: true,
      trim: true,
    },
    text: {
      type: String,
      required: true,
      trim: true,
    },
    category: {
      type: String,
      enum: ['savings', 'budgeting', 'investment', 'debt', 'emergency_fund', 'goals'],
      required: true,
    },
    priority: {
      type: String,
      enum: ['high', 'medium', 'low'],
      default: 'medium',
    },
    reasoning: {
      type: String,
      required: true,
    },
    potentialMonthlyImpact: {
      type: Number,
      default: 0,
    },
    status: {
      type: String,
      enum: ['new', 'seen', 'applied', 'dismissed'],
      default: 'new',
    },
  },
  {
    timestamps: true,
  }
);

// Prevent duplicate recommendations of the same active rule for a user
recommendationSchema.index({ userId: 1, ruleId: 1, status: 1 });

module.exports = mongoose.model('Recommendation', recommendationSchema);
